Below is a compact, practical implementation of convert_ast_to_graph (and small supporting pieces) for the simplifying assumptions you gave: SELECT with FROM and WHERE only; the SQL is already parsed into an AST. The implementation builds a small relational-algebra tree using nodes: Scan, Select (σ), Join, Project (π). It also pushes down single-table predicates to scans when possible and attaches multi-table predicates as join conditions or selections above joins.

Assumed AST shape (one convenient convention used in the code):
- ast['select']: list of column specs, e.g. ['a.id', 'b.name'] or ['*']
- ast['from']: list of dicts { 'table': 'users', 'alias': 'a' } (alias optional)
- ast['where']: expression tree or None. Expression nodes can be:
  - {'type':'binary_op', 'op':'=', 'left': <expr>, 'right': <expr>}
  - {'type':'column', 'table': 'a', 'name':'id'}
  - {'type':'literal', 'value': 100}
  - {'type':'and', 'left': <expr>, 'right': <expr>} (conjunctions used for splitting predicates)

Code (Python):

```python
# Relational algebra node classes
class RelAlgNode:
    def __init__(self, kind, **kwargs):
        self.kind = kind
        self.attrs = kwargs
        self.children = []
    def add_child(self, child):
        self.children.append(child)
    def __repr__(self):
        return f"{self.kind}({self.attrs})"

class Scan(RelAlgNode):
    def __init__(self, table, alias=None):
        super().__init__('Scan', table=table, alias=alias)

class Select(RelAlgNode):
    def __init__(self, predicate):
        super().__init__('Select', predicate=predicate)

class Join(RelAlgNode):
    def __init__(self, join_condition=None):
        super().__init__('Join', condition=join_condition)

class Project(RelAlgNode):
    def __init__(self, columns):
        super().__init__('Project', columns=columns)

# Helper utilities to inspect expression ASTs
def collect_tables_in_expr(expr):
    """Return set of table aliases referenced by expr."""
    if expr is None:
        return set()
    t = expr.get('type')
    if t == 'column':
        return {expr.get('table')}
    if t == 'literal':
        return set()
    if t in ('binary_op',):
        return collect_tables_in_expr(expr['left']) | collect_tables_in_expr(expr['right'])
    if t == 'and':
        return collect_tables_in_expr(expr['left']) | collect_tables_in_expr(expr['right'])
    # extend for other node types if present
    return set()

def flatten_conjuncts(expr):
    """Return list of conjunct predicate expressions from expr (AND-splitting).
    If expr is None, returns []."""
    if not expr:
        return []
    if expr.get('type') == 'and':
        return flatten_conjuncts(expr['left']) + flatten_conjuncts(expr['right'])
    return [expr]

# The main convert function
def convert_ast_to_graph(ast):
    # 1) Build Scan nodes for each FROM item
    scans = []
    alias_map = {}  # alias -> scan node
    for frm in ast.get('from', []):
        if isinstance(frm, str):
            table_name = frm
            alias = None
        else:
            table_name = frm.get('table')
            alias = frm.get('alias') or table_name
        scan = Scan(table_name, alias=alias)
        scans.append(scan)
        alias_map[alias] = scan

    if not scans:
        raise ValueError('FROM must contain at least one table')

    # 2) Combine scans into a join tree (left-deep cross joins initially)
    current = scans[0]
    for scan in scans[1:]:
        j = Join(join_condition=None)
        j.add_child(current)
        j.add_child(scan)
        current = j

    root = current

    # 3) Split WHERE into conjunct predicates and push predicates down
    where = ast.get('where')
    predicates = flatten_conjuncts(where)

    remaining_preds_for_root = []
    for pred in predicates:
        tables = collect_tables_in_expr(pred)
        if len(tables) == 0:
            # predicate contains no table refs (constant boolean) -> attach at root
            remaining_preds_for_root.append(pred)
        elif len(tables) == 1:
            # push down to the scan for that table (wrap that scan in a Select)
            alias = next(iter(tables))
            target_scan = alias_map.get(alias)
            if target_scan is None:
                # alias not found; treat as root predicate
                remaining_preds_for_root.append(pred)
                continue
            # If the scan is already wrapped by a Select, append above it
            parent = Select(pred)
            # replace the scan node in the tree with Select(scan)
            replace_node_in_tree(root, target_scan, parent)
            parent.add_child(target_scan)
        else:
            # predicate references multiple tables -> a join predicate
            # Attach to the highest join that contains all referenced tables.
            # For our simple left-deep tree, the root join contains them; attach to root.
            remaining_preds_for_root.append(pred)

    # 4) If there are remaining predicates, wrap root in a Select (join-level selections)
    if remaining_preds_for_root:
        # combine remaining predicates back into AND form if more than one
        combined = combine_conjuncts(remaining_preds_for_root)
        sel = Select(combined)
        sel.add_child(root)
        root = sel

    # 5) Project: if select list is not ['*'], create Project node
    select_list = ast.get('select', ['*'])
    if not (len(select_list) == 1 and select_list[0] == '*'):
        proj = Project(select_list)
        proj.add_child(root)
        root = proj

    return root

# Utility to combine list of predicates back into nested ANDs
def combine_conjuncts(preds):
    if not preds:
        return None
    it = iter(preds)
    acc = next(it)
    for p in it:
        acc = {'type': 'and', 'left': acc, 'right': p}
    return acc

# Utility to replace a node in the tree with new_node (searches tree by identity)
def replace_node_in_tree(root, target, new_node):
    # Depth-first search to find and replace target in children lists
    if root is target:
        raise RuntimeError('Attempted to replace the root node directly')
    stack = [root]
    while stack:
        node = stack.pop()
        for i, child in enumerate(node.children):
            if child is target:
                node.children[i] = new_node
                return True
            stack.append(child)
    return False

# Pretty-print helper for debugging
def pprint_tree(node, indent=0):
    pad = '  ' * indent
    print(pad + f"{node.kind} {node.attrs}")
    for c in node.children:
        pprint_tree(c, indent + 1)

# Example usage
if __name__ == '__main__':
    ast = {
        'select': ['a.id', 'b.amount'],
        'from': [ {'table': 'users', 'alias': 'a'}, {'table':'orders','alias':'b'} ],
        'where': {
            'type': 'and',
            'left': {
                'type': 'binary_op', 'op': '=',
                'left': {'type':'column','table':'a','name':'id'},
                'right': {'type':'column','table':'b','name':'user_id'}
            },
            'right': {
                'type': 'binary_op', 'op': '>',
                'left': {'type':'column','table':'b','name':'amount'},
                'right': {'type':'literal','value': 100}
            }
        }
    }

    graph = convert_ast_to_graph(ast)
    pprint_tree(graph)
```

Notes and extensions:
- The code assumes a consistent AST shape. If your parser produces a different AST, adapt the helper functions collect_tables_in_expr and flatten_conjuncts accordingly.
- For more complex FROM (e.g., explicit JOIN syntax with types), you would create Join nodes according to join types and attach join conditions directly there.
- More advanced optimization (predicate reordering, merging selects, cost-based join ordering) would be added after this basic construction.

If you want, I can adapt this to your exact AST representation or extend it to support explicit JOIN clauses and simple index-aware predicate pushdown.

