Below is a compact, working AudioWorkletProcessor implementation of a chorus effect (JS) plus a short main-thread snippet showing how to load and control it. The processor implements multiple modulated delay voices, fractional delays with linear interpolation, optional feedback, and dry/wet mix.

// chorus-processor.js
class ChorusProcessor extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name: 'rate', defaultValue: 1.5, minValue: 0, maxValue: 10 },        // LFO Hz
      { name: 'depth', defaultValue: 0.003, minValue: 0, maxValue: 0.02 },    // modulation amplitude in seconds (3 ms)
      { name: 'delay', defaultValue: 0.015, minValue: 0, maxValue: 0.05 },    // base delay in seconds (15 ms)
      { name: 'feedback', defaultValue: 0.0, minValue: -0.95, maxValue: 0.95 },
      { name: 'mix', defaultValue: 0.5, minValue: 0, maxValue: 1 },          // 0 = dry, 1 = wet
      { name: 'voices', defaultValue: 2, minValue: 1, maxValue: 6, automationRate: 'k-rate' }
    ];
  }

  constructor(options) {
    super();
    this._sr = sampleRate;

    this._maxDelaySec = 0.1; // 100 ms max delay buffer
    this._maxDelaySamps = Math.ceil(this._maxDelaySec * this._sr) + 2;

    this._buffers = [];      // per channel circular buffer (Float32Array)
    this._writeIndex = 0;

    // Precompute phase offsets for voices so they are not identical
    this._voicePhaseOffsets = [0, Math.PI]; // can extend for more voices
    this._maxVoices = 6;
    this._voicePhases = new Float32Array(this._maxVoices);
  }

  _ensureBuffers(channels) {
    while (this._buffers.length < channels) {
      this._buffers.push(new Float32Array(this._maxDelaySamps));
    }
  }

  process(inputs, outputs, parameters) {
    const input = inputs[0];
    const output = outputs[0];
    if (!input || input.length === 0) return true; // no input

    const channels = Math.min(input.length, output.length);
    this._ensureBuffers(channels);

    // k-rate param values appear as single-element arrays in parameters[...][0]
    const voicesVal = (parameters.voices.length > 0) ? Math.max(1, Math.min(this._maxVoices, Math.round(parameters.voices[0]))) : 2;

    const blockSize = output[0].length;

    for (let ch = 0; ch < channels; ch++) {
      const inCh = input[ch];
      const outCh = output[ch];
      const buf = this._buffers[ch];
      let write = this._writeIndex;

      for (let i = 0; i < blockSize; i++) {
        const x = inCh ? inCh[i] : 0;

        // Per-sample params (automation-rate) are arrays; if length>1 they're a-rate
        const rate = (parameters.rate.length > 1) ? parameters.rate[i] : parameters.rate[0];
        const depth = (parameters.depth.length > 1) ? parameters.depth[i] : parameters.depth[0];
        const delaySec = (parameters.delay.length > 1) ? parameters.delay[i] : parameters.delay[0];
        const feedback = (parameters.feedback.length > 1) ? parameters.feedback[i] : parameters.feedback[0];
        const mix = (parameters.mix.length > 1) ? parameters.mix[i] : parameters.mix[0];

        // write current input + feedback contribution placeholder (we will override buffer[write] with feedback applied)
        // compute wet sum from voices
        let wet = 0;
        for (let v = 0; v < voicesVal; v++) {
          // maintain per-voice phase
          let phase = this._voicePhases[v] || 0;
          const phaseOffset = this._voicePhaseOffsets[v % this._voicePhaseOffsets.length] || 0;

          const mod = Math.sin(phase + phaseOffset);
          const curDelay = delaySec + mod * depth; // seconds
          const delaySamples = curDelay * this._sr;

          // Compute read index (circular)
          let readIndex = write - delaySamples;
          // wrap into [0, buf.length)
          while (readIndex < 0) readIndex += this._maxDelaySamps;
          while (readIndex >= this._maxDelaySamps) readIndex -= this._maxDelaySamps;

          // linear interpolation
          const i0 = Math.floor(readIndex) | 0;
          const i1 = (i0 + 1) % this._maxDelaySamps;
          const frac = readIndex - i0;
          const s0 = buf[i0];
          const s1 = buf[i1];
          wet += s0 + frac * (s1 - s0);

          // advance phase
          const phaseInc = 2 * Math.PI * rate / this._sr;
          phase += phaseInc;
          // keep phase in 0..2pi
          if (phase > Math.PI * 2) phase -= Math.PI * 2;
          this._voicePhases[v] = phase;
        }

        wet = wet / voicesVal; // average voices

        // store incoming sample with feedback applied
        buf[write] = x + wet * feedback;

        // mix dry/wet
        outCh[i] = x * (1 - mix) + wet * mix;

        // increment write pointer
        write++;
        if (write >= this._maxDelaySamps) write = 0;
      }

      // store back per-channel write index (same for all channels)
      this._writeIndex = write;
    }

    return true;
  }
}

