// main.js (example)
async function setupChorusExample(sourceNode) {
  const ctx = sourceNode.context || new AudioContext();
  await ctx.audioWorklet.addModule('chorus-processor.js');

  const chorusNode = new AudioWorkletNode(ctx, 'chorus-processor', {
    outputChannelCount: [2],
    parameterData: {
      rate: 1.5,
      depth: 0.003,
      delay: 0.015,
      feedback: 0.0,
      mix: 0.5,
      voices: 2
    }
  });

  sourceNode.connect(chorusNode).connect(ctx.destination);

  // Example of changing parameters
  const rateParam = chorusNode.parameters.get('rate');
  rateParam.setValueAtTime(0.8, ctx.currentTime);
  rateParam.linearRampToValueAtTime(2.5, ctx.currentTime + 4);

  // Change mix
  chorusNode.parameters.get('mix').setValueAtTime(0.6, ctx.currentTime);

  return chorusNode;
}

Notes and tweaks you may want:
- Depth and delay units are in seconds (depth ~ 0.002–0.008, delay ~ 0.01–0.03 are typical for chorus).
- Increase voices to 3–4 for a thicker chorus and add different phase offsets per voice.
- The implementation uses a single circular buffer per channel with feedback applied by writing back wet*feedback into the buffer; this is simple and efficient.
- For higher fidelity fractional delay, replace linear interpolation with allpass or higher-order interpolation.

